import {icon,esc,button,badge,money,empty} from './ui.js';
import {renderStudio,handleStudio,agents,changeSlide} from './studio.js';
import {renderDetail,handleOnboarding} from './onboarding.js';
import {renderDashboard,handleDashboard} from './dashboard.js';
import {openRay,handleRay} from './ray.js';

const STORAGE='razorpay-agent-studio-v1';
const initial=()=>({installed:false,paused:false,pending:['intro','sai','shivalik','finch','glow','label'],labelPending:['khan','verma','dsouza'],resolved:{},buyerOverrides:{},extraActivity:[],extraLearned:[],labelsCount:120,range:'since',learnedMarks:{},connectors:{},notifications:{},agentPaused:{},drafts:[],config:{tiers:[8,12,15],moq:10,quoteLimit:15000,confidence:80,weeklyMessages:2,followups:3,quietStart:'21:00',quietEnd:'09:00',credit:false,approvalWhatsapp:true,mode:'review',weeklyBrief:true,languages:['English','Hindi']}});
function load(){try{const s=JSON.parse(localStorage.getItem(STORAGE));if(s&&Array.isArray(s.pending)&&Array.isArray(s.labelPending))return {...initial(),...s,config:{...initial().config,...s.config}};}catch{}return initial();}
let state=load();const ui={slide:0,category:'all',route:'',sidebar:false};let toastTimer,overlayFocus,overlayFocusDescriptor,carouselHold=false;
const ctx={state,ui,icon,esc,button,badge,money,nav,update,rerender:render,toast,modal:html=>overlay(html,false),drawer:html=>overlay(html,true),closeOverlay,log,resolve,label,saveConfig,activate,pause,resume};
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify(state));}catch{}}
function update(patch){Object.assign(state,patch);persist();render();}
function saveConfig(patch){state.config={...state.config,...patch};persist();render();}
function nav(route){const aliases={studio:'/studio/home',dashboard:'/agent/business/dashboard',detail:'/agent/business',approvals:'/agent/business/approvals',activity:'/agent/business/activity',settings:'/agent/business/settings',buyers:'/agent/business/buyers'};route=aliases[route]||route;if(!route.startsWith('/'))route='/'+route;closeOverlay(false);ui.sidebar=false;ui.rangeOpen=false;if(location.hash==='#'+route)render();else location.hash=route;}
function log(entry){state.extraActivity.unshift({id:'event-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),time:new Intl.DateTimeFormat('en-IN',{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Kolkata'}).format(new Date()),date:'Today',status:'Done',by:'Neha · Demo',manual:true,cat:'guardrails',...entry});persist();}
function resolve(id,action='approved',entry={},override){if(!state.pending.includes(id))return;state.pending=state.pending.filter(x=>x!==id);state.resolved[id]=action;if(override?.id)state.buyerOverrides[override.id]={...state.buyerOverrides[override.id],...override};log({title:action==='rejected'?'Request declined':'Request approved',buyer:id,...entry});render();}
function label(id,value,name){const statuses={business:'Confirmed business · intro queued',not:'Not a business',unsure:'Not sure · watching for signals',pause:'Outreach paused',exclude:'Excluded from agent'};const outreachOnly=['pause','exclude'].includes(value);state.buyerOverrides[id]={...state.buyerOverrides[id],id,status:statuses[value],label:value,...(!outreachOnly?{detection:value==='business'?'Confirmed by you':value==='not'?'Not a business':'Possible'}:{}),tone:value==='business'?'positive':value==='pause'?'notice':'neutral',groups:value==='business'?['new']:value==='not'?['notbiz']:[]};const had=state.labelPending.includes(id);state.labelPending=state.labelPending.filter(x=>x!==id);if(['business','not','unsure'].includes(value))state.labelsCount++;if(!state.labelPending.length)state.pending=state.pending.filter(x=>x!=='label');log({title:value==='business'?'Confirmed as a business':value==='not'?'Marked as not a business':value==='unsure'?'Marked as not sure':value==='pause'?'Outreach paused':'Excluded from agent',buyer:name,cat:['business','not','unsure'].includes(value)?'learning':'guardrails',detail:value==='business'?'Added to the next intro queue':value==='not'?'Removed from outreach; similar patterns count for less':'Buyer status updated by Neha'});if(had&&value!=='unsure'){const learning={khan:'Repeat bedsheet orders to Kota homes now need a PG name or a shared payer before they are flagged.',verma:'Office-park deliveries now look for a work email or a GSTIN note.',dsouza:'A villa address alone now counts for less when identifying a business.'};state.extraLearned.unshift({id:'learn-'+Date.now(),text:value==='business'?`${name}’s purchase pattern now counts as a confirmed business signal.`:learning[id]||`${name}’s pattern now counts for less.`,isNew:true});}persist();render();toast('Updated '+name+' · '+statuses[value]);}
function activate(){state.installed=true;state.paused=false;persist();closeOverlay(false);nav('/agent/business/dashboard');toast('B2B Customer Agent is live in this demo · review-first mode.');}
function pause(){modal(`<div class="modal-body"><div class="modal-head"><h2>Pause B2B Customer Agent?</h2>${button(icon('x',17),'overlay-close','ghost','aria-label="Close"')}</div><p>Messages, calls and quotes will stop immediately in this demo. Your approvals stay in the queue.</p><p class="muted small" style="margin-top:12px">Resume any time from the dashboard. Nothing is deleted.</p><div class="modal-actions">${button('Keep running','overlay-close')}${button(icon('pause',14)+' Pause agent','agent-pause-confirm','primary')}</div></div>`);}
function resume(){state.paused=false;log({title:'Agent resumed',buyer:'All buyers',detail:'Back to review-first, within your rules.'});closeOverlay();render();toast('B2B Customer Agent resumed.');}
function modal(html){overlay(html,false);}
function overlay(html,drawer){const root=document.getElementById('overlay-root');const existed=!!root.firstChild;if(!existed){overlayFocus=document.activeElement;overlayFocusDescriptor={action:overlayFocus?.dataset?.action,id:overlayFocus?.dataset?.id,key:overlayFocus?.dataset?.key,href:overlayFocus?.getAttribute('href')};}const active=document.activeElement;const key=active?.dataset?.action,actionId=active?.dataset?.id,controlKey=active?.dataset?.key;const selection=active?.selectionStart;const scrollAreas=[...root.querySelectorAll('.ray-conversation')].map(el=>({className:el.className,top:el.scrollTop}));root.innerHTML=`<div class="overlay-backdrop ${drawer?'drawer-backdrop':''}" data-backdrop><div class="modal-panel ${drawer?'drawer-panel':''}" ${/role="dialog"/.test(html)?'':'role="dialog" aria-modal="true"'} tabindex="-1">${html}</div></div>`;document.getElementById('app').inert=true;for(const position of scrollAreas){const area=[...root.querySelectorAll('.ray-conversation')].find(el=>el.className===position.className);if(area)area.scrollTop=position.top;}const panel=root.querySelector('.modal-panel'),heading=panel.querySelector('h2,h1,h3');if(heading&&!panel.querySelector('[role="dialog"]')){if(!heading.id)heading.id='active-modal-title';panel.setAttribute('aria-labelledby',heading.id);}if(existed&&key){const target=[...root.querySelectorAll('[data-action]')].find(x=>x.dataset.action===key&&(!actionId||x.dataset.id===actionId)&&(!controlKey||x.dataset.key===controlKey));if(target){target.focus({preventScroll:true});if(selection!=null&&target.setSelectionRange)try{target.setSelectionRange(selection,selection);}catch{}return;}}(panel.querySelector('input:not([type=checkbox]):not([type=radio]),textarea,button:not(:disabled),a')||panel).focus({preventScroll:true});}
function closeOverlay(restore=true){const existed=!!document.getElementById('overlay-root').firstChild;const s=ui.install;if(s){(s.timers||[]).forEach(clearTimeout);if(s.scanTimer)clearInterval(s.scanTimer);}ui.install=null;document.getElementById('overlay-root').innerHTML='';document.getElementById('app').inert=false;if(restore&&existed){const d=overlayFocusDescriptor||{};const replacement=[...document.querySelectorAll('#app [data-action],#app a[href]')].find(x=>d.action?x.dataset.action===d.action&&(!d.id||x.dataset.id===d.id)&&(!d.key||x.dataset.key===d.key):d.href&&x.getAttribute('href')===d.href);(overlayFocus?.isConnected?overlayFocus:replacement||document.getElementById('main')).focus({preventScroll:true});}}
function toast(msg){clearTimeout(toastTimer);document.getElementById('toast-root').innerHTML=`<div class="toast">${icon('check-circle',17)}<span>${esc(msg)}</span><button data-action="toast-close" aria-label="Dismiss notification">${icon('x',14)}</button></div>`;toastTimer=setTimeout(()=>document.getElementById('toast-root').innerHTML='',4500);}
const navItems=[['home','Home','home'],['transactions','Transactions','transactions'],['settlements','Settlements','bank'],['reports','Reports','file'],['studio','Agent Studio','monitor'],['credit','Credit Card','credit-card'],['vendors','Vendor Payments','folder'],['tax','Tax and Compliance','percent'],['ray','Ray AI','sparkles']];
document.getElementById('app').innerHTML=`<div class="app-shell"><header class="topbar"><button class="mobile-menu" data-action="sidebar-toggle" aria-label="Toggle navigation" aria-expanded="false">${icon('menu',20)}</button><a class="brand" href="#/studio/home" aria-label="Razorpay Agent Studio"><img src="./assets/razorpay-logo.webp" alt="Razorpay" width="130" height="28"></a><nav class="product-nav" aria-label="Razorpay products"><button class="top-link active" data-route="/studio/home">Payments</button><button class="top-link" data-route="/payments/banking">Banking</button><button class="top-link" data-route="/payments/payroll">Payroll</button><button class="top-link" data-action="more-products">More ${icon('chevron-down',10)}</button></nav><div class="top-tools"><button class="global-search" data-action="command-open" aria-label="Search pages and agents">${icon('search',14)}<span>Search</span><kbd>⌘ K</kbd></button><button class="top-link reset-icon" data-action="demo-reset" aria-label="Reset demo">${icon('refresh',13)} Reset</button><button class="top-icon" data-action="notifications" aria-label="Notifications">${icon('bell',17)}<span class="notification-dot"></span></button><button class="avatar" data-action="profile" aria-label="Open Neha's profile">NA</button></div></header><div class="workspace"><aside class="sidebar" id="sidebar" aria-label="Main navigation">${navItems.map(([id,name,ic])=>`<button class="nav-item" data-route="${id==='studio'?'/studio/home':'/payments/'+id}" data-nav="${id}">${icon(ic,17)}<span>${name}</span>${id==='studio'?badge('Beta','green'):''}</button>`).join('')}</aside><main id="main" class="main" tabindex="-1"><div class="page" id="content"></div></main></div></div>`;
function route(){return (location.hash.slice(1)||'/studio/home').replace(/\/$/,'');}
function render(){
 const path=route(),parts=path.split('/').filter(Boolean),changed=ui.route!==path;
 const active=document.activeElement,key=active?.dataset?.action,name=active?.dataset?.key,actionId=active?.dataset?.id,focusId=active?.id,selection=active?.selectionStart;const oldScroll=document.getElementById('main').scrollTop;
 ui.route=path;const isAgent=parts[0]==='agent',isStudio=parts[0]==='studio',tab=parts[2]||'detail';let html;
 if(isStudio)html=renderStudio(ctx,parts[1]||'home');
 else if(isAgent){const id=parts[1]||'business';if(parts.length<3)html=renderDetail(ctx,id);else if(id==='business')html=dashHeader(tab)+renderDashboard(ctx,tab);else html=genericDashboard(id);}
 else if(parts[0]==='payments')html=renderPayments(parts[1]||'home');
 else html=empty('Page not found','Head back to Agent Studio to continue.',`<a class="btn btn-primary" href="#/studio/home">Open Agent Studio</a>`);
 document.getElementById('content').innerHTML=`<div class="${changed?'page-enter':''}">${html}</div><footer class="page-footer"><span>Razorpay · Agent Studio prototype</span><span>Synthetic data · No external connections</span></footer>`;
 document.querySelectorAll('[data-nav]').forEach(el=>el.classList.toggle('active',el.dataset.nav===(isAgent||isStudio?'studio':parts[1])));
 const sidebar=document.getElementById('sidebar'),mobile=matchMedia('(max-width:700px)').matches;sidebar.classList.toggle('open',ui.sidebar);sidebar.inert=mobile&&!ui.sidebar;document.querySelector('.mobile-menu').setAttribute('aria-expanded',String(ui.sidebar));document.querySelector('.sidebar-shade')?.remove();if(mobile&&ui.sidebar){const shade=document.createElement('div');shade.className='sidebar-shade';shade.dataset.action='sidebar-toggle';document.querySelector('.workspace').append(shade);}
 document.getElementById('main').scrollTop=changed?0:oldScroll;
 const label=isStudio?'Agent Studio':isAgent?(agents.find(a=>a.id===parts[1])?.name||'Agent'):(navItems.find(x=>x[0]===parts[1])?.[1]||'Razorpay');document.title=label+' · Razorpay';
 if(!changed&&(key||focusId)){const candidate=focusId?document.getElementById(focusId):[...document.querySelectorAll('#content [data-action]')].find(x=>x.dataset.action===key&&(!name||x.dataset.key===name)&&(!actionId||x.dataset.id===actionId));if(candidate){candidate.focus({preventScroll:true});if(selection!=null&&candidate.setSelectionRange)try{candidate.setSelectionRange(selection,selection);}catch{}}}
}
const DATE_RANGES = [
 {id:'week',label:'This week',dates:'12–18 Oct 2026'},
 {id:'d30',label:'Last 30 days',dates:'13 Sep–12 Oct 2026'},
 {id:'since',label:'Since activation',dates:'29 Aug–12 Oct 2026'},
 {id:'q',label:'This quarter',dates:'Oct–Dec 2026'}
];
function dateControl(){
 const selected=DATE_RANGES.find(r=>r.id===state.range)||DATE_RANGES[2];
 return `<div class="date-control"><button type="button" class="btn date-trigger" data-action="date-menu-toggle" aria-label="Date range: ${selected.label}" aria-haspopup="menu" aria-expanded="${!!ui.rangeOpen}" aria-controls="date-range-menu">${icon('calendar',16)}<span>${selected.label}</span>${icon('chevron-down',13)}</button>${ui.rangeOpen?`<div id="date-range-menu" class="date-menu" role="menu" aria-label="Dashboard date range">${DATE_RANGES.map(r=>`<button type="button" class="date-option ${r.id===selected.id?'selected':''}" role="menuitemradio" aria-checked="${r.id===selected.id}" data-action="date-range-pick" data-range="${r.id}"><span><strong>${r.label}</strong><small>${r.dates}</small></span>${r.id===selected.id?icon('check',16):'<span class="date-check-space"></span>'}</button>`).join('')}</div>`:''}</div>`;
}
function closeDateMenu(focus=false){
 ui.rangeOpen=false;
 document.getElementById('date-range-menu')?.remove();
 const trigger=document.querySelector('[data-action="date-menu-toggle"]');
 trigger?.setAttribute('aria-expanded','false');
 if(focus)trigger?.focus({preventScroll:true});
}
function dashHeader(tab){
 return `<div class="dash-heading"><button class="back-button" data-route="/studio/mine" aria-label="Back to My agents">${icon('arrow-left',19)}</button><div class="icon-tile">${icon('store',23)}</div><div class="dash-agent-title"><div class="row dash-title-line"><h1>B2B Customer Agent</h1><span class="healthy" style="color:${state.paused?'#a66a13':''}"><span class="status-dot" style="background:${state.paused?'#d7a037':''}"></span>${state.paused?'PAUSED':'LIVE'}</span></div><div class="meta">Review-first · ${state.installed?'day 45':'demo preview'}</div></div><div class="dash-tools">${dateControl()}${button(icon('sparkles',16)+'<span>Ask Ray</span>','dashboard-ray','secondary','title="Ask Ray to summarize your dashboard or help with approvals"')}${button(icon(state.paused?'play':'pause',14)+`<span class="control-label">${state.paused?'Resume agent':'Pause agent'}</span>`,'agent-pause','secondary',`aria-label="${state.paused?'Resume':'Pause'} agent" title="${state.paused?'Resume':'Pause'} agent"`)}</div></div><nav class="tabs dash-tabs" aria-label="B2B agent sections">${[['dashboard','Dashboard'],['approvals','Approvals'],['activity','Activity'],['settings','Settings']].map(([id,label])=>`<a class="tab ${tab===id||(tab==='buyers'&&id==='activity')?'active':''}" href="#/agent/business/${id}" ${tab===id?'aria-current="page"':''}>${label}${id==='approvals'&&state.pending.length?badge(state.pending.length,'blue'):''}</a>`).join('')}</nav>${state.paused?`<div class="callout warning" style="margin-bottom:20px">${icon('pause',19)}<span><strong>B2B Customer Agent is paused.</strong> Your approvals are waiting. Resume to continue demo outreach.</span>${button('Resume','agent-resume','primary')}</div>`:''}`;
}

const transactions=[['pay_QK8F21','Urban Nest Co-living','UPI',15246,'Captured','12 Oct, 11:42'],['pay_QK8D19','Glow Salon','Card',27122,'Captured','12 Oct, 11:36'],['pay_QK8B07','Sai Krupa PG','UPI',10521,'Captured','12 Oct, 10:58'],['pay_QK7A62','Khan Family','UPI',3592,'Captured','12 Oct, 10:24'],['pay_QK6C31','Finch Studio','Netbanking',9886,'Pending','11 Oct, 18:14'],['pay_QK6B09','Shivalik Stay','UPI',8140,'Refunded','11 Oct, 16:32'],['pay_QK5D12','Backpackers Hostel','Card',6270,'Captured','11 Oct, 15:49'],['pay_QK5A44','Mehta Family','UPI',4490,'Captured','11 Oct, 14:36']];
function renderPayments(page){
 const titles={home:'Your business, at a glance',transactions:'Transactions',settlements:'Settlements',reports:'Reports',credit:'Credit Card',vendors:'Vendor Payments',tax:'Tax and Compliance',ray:'Ray AI',banking:'Banking',payroll:'Payroll'};
 const heading=`<div class="page-title"><div><h1>${titles[page]||'Payments'}</h1><p>Kesar Linen · Demo workspace · Monday, 12 October 2026</p></div>${badge('Synthetic data','blue')}</div>`;
 if(page==='home')return heading+`<div class="grid-3">${[['Payment volume','₹12.84 L','+18.4% this month'],['Available balance','₹3.42 L','Next settlement: 13 October'],['Successful payments','98.6%','428 payments this month']].map(([label,val,sub])=>`<div class="card payment-metric"><span class="muted small">${label}</span><strong>${val}</strong><p>${sub}</p></div>`).join('')}</div><div class="callout green" style="margin:23px 0">${icon('sparkles',19)}<span><strong>Your next growth opportunity:</strong> 44 new business buyers identified this week.</span><a href="#/agent/business/dashboard" class="btn btn-primary">View agent ${icon('arrow-right',13)}</a></div><div class="section-head"><h2>Recent payments</h2><a href="#/payments/transactions" class="small">View all</a></div>`+transactionTable(transactions.slice(0,5));
 if(page==='transactions'){const search=(ui.paymentSearch||'').toLowerCase(),status=ui.paymentStatus||'All statuses',rows=transactions.filter(x=>x.join(' ').toLowerCase().includes(search)&&(status==='All statuses'||x[4]===status));return heading+`<div class="toolbar"><label class="search-field">${icon('search',17)}<input data-action="payment-search" aria-label="Search payments" placeholder="Search payments or customers" value="${esc(ui.paymentSearch||'')}"></label><select data-action="payment-status" aria-label="Payment status">${['All statuses','Captured','Pending','Refunded'].map(x=>`<option ${status===x?'selected':''}>${x}</option>`).join('')}</select><span class="spacer"></span>${button(icon('download',15)+' Export CSV','payment-export')}</div>`+transactionTable(rows);}
 if(page==='settlements')return heading+`<div class="grid-3">${[['Next settlement','₹1,82,440','13 Oct 2026 · 09:00'],['Settled this month','₹9,64,208','8 completed settlements'],['Account ending','•••• 4107','HDFC Bank · Kesar Linen']].map(([label,val,sub])=>`<div class="card payment-metric"><span class="muted small">${label}</span><strong>${val}</strong><p>${sub}</p></div>`).join('')}</div><div class="card" style="margin-top:24px"><div class="section-head"><h2>Settlement history</h2>${button(icon('download',14)+' Download statement','payment-export','secondary','data-kind="settlements"')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Settlement</th><th>Date</th><th>Amount</th><th>Status</th></tr></thead><tbody>${[['set_QK810','10 Oct 2026','₹1,24,808'],['set_QK721','8 Oct 2026','₹98,246'],['set_QK604','6 Oct 2026','₹1,56,310']].map(x=>`<tr><td>${x[0]}</td><td>${x[1]}</td><td>${x[2]}</td><td>${badge('Settled','green')}</td></tr>`).join('')}</tbody></table></div></div>`;
 if(page==='reports')return heading+`<div class="grid-3">${[['Payments report','Every payment, method and status.','transactions'],['Settlement report','Your settlement and fee summary.','bank'],['Agent activity report','Every decision and buyer interaction.','monitor']].map(([name,desc,ic],i)=>`<div class="card stack"><div class="icon-tile blue">${icon(ic,23)}</div><h3>${name}</h3><p class="muted small">${desc}</p>${button(icon('download',14)+' Download CSV',i===2?'report-agent-export':'payment-export','secondary',i===1?'data-kind="settlements"':'')}</div>`).join('')}</div>`;
 if(page==='ray')return heading+`<div class="card" style="max-width:780px"><div class="row"><span class="icon-tile blue">${icon('sparkles',23)}</span><h2>Ask about your business</h2></div><p class="muted" style="margin-top:18px">Explore your synthetic revenue, buyers and pending approvals.</p><div class="chips" style="margin-top:18px">${['How is my business doing?','Which approvals need me?','Where can I grow?'].map(x=>button(esc(x),'ray-prompt','secondary',`data-prompt="${esc(x)}"`)).join('')}</div><form class="question-form" id="ray-form"><input id="ray-question" aria-label="Ask Ray AI" placeholder="Ask about your business…" maxlength="300"><button class="btn btn-primary" type="submit">Ask ${icon('arrow-right',15)}</button></form><div id="ray-answer"></div><p class="muted small" style="margin-top:18px">Demo assistant · Responses are generated from this prototype’s synthetic data.</p></div>`;
 const data={credit:['credit-card','A smarter way to pay for business','₹2,00,000','Available demo credit','Statement balance ₹24,880 · Due 20 October'],vendors:['folder','Pay vendors, stay organised','₹78,400','Upcoming vendor payments','3 scheduled payments · Next: Panipat Textiles, ₹42,000'],tax:['receipt','Your compliance overview','₹18,420','Estimated GST this month','GSTIN verified · October filing due 20 November'],banking:['bank','Business banking overview','₹3,42,580','Available demo balance','HDFC Bank · Current account ending 4107'],payroll:['users','Your team, paid on time','₹1,84,000','October payroll estimate','8 team members · Next payday: 31 October']}[page]||['monitor','Your workspace','—','Demo overview',''];
 return heading+`<div class="grid-2"><div class="card payment-metric"><div class="icon-tile blue">${icon(data[0],24)}</div><h2 style="margin-top:16px">${data[1]}</h2><span class="muted small" style="display:block;margin-top:20px">${data[3]}</span><strong>${data[2]}</strong><p>${data[4]}</p></div><div class="card stack"><h2>Demo workspace</h2><p class="muted">Explore your business operations using sample records. Manage your AI workforce in Agent Studio.</p><a href="#/studio/home" class="btn btn-primary" style="align-self:flex-start">Open Agent Studio ${icon('arrow-right',14)}</a>${button(icon('download',15)+' Export demo records','payment-export')}</div></div>`;
}
function transactionTable(rows){return `<div class="card flush table-wrap"><table class="data-table"><thead><tr><th>Payment ID</th><th>Customer</th><th>Method</th><th>Amount</th><th>Status</th><th>Created</th></tr></thead><tbody>${rows.map(x=>`<tr><td><button class="link-button" data-action="payment-detail" data-id="${x[0]}">${x[0]}</button></td><td>${x[1]}</td><td>${x[2]}</td><td class="mono">${money(x[3])}</td><td>${badge(x[4],x[4]==='Captured'?'green':x[4]==='Pending'?'orange':'neutral')}</td><td class="muted small">${x[5]}</td></tr>`).join('')}</tbody></table>${!rows.length?empty('No matching payments','Try a different search or status.'):''}</div>`;}
function genericDashboard(id){const a=agents.find(x=>x.id===id);if(!a)return empty('Agent not found');return `<a href="#/studio/mine" class="btn btn-ghost">${icon('arrow-left',15)} My agents</a><div class="page-title" style="margin-top:20px"><div class="row"><div class="icon-tile ${a.tone}">${icon(a.icon,25)}</div><div><h1>${a.name}</h1><p>Review-first · Synthetic demo activity</p></div></div>${badge(state.agentPaused[id]?'Paused':'Healthy',state.agentPaused[id]?'orange':'green')}</div><div class="grid-3">${[['Actions completed','28'],['Ready for review','3'],['Time saved','4.2 hrs']].map(([label,val])=>`<div class="card payment-metric"><span class="muted small">${label}</span><strong>${val}</strong><p>This week · synthetic data</p></div>`).join('')}</div><div class="card stack" style="margin-top:24px"><div class="row between"><h2>Latest activity</h2>${button(icon('pause',14)+' '+(state.agentPaused[id]?'Resume':'Pause')+' agent','studio-pause','secondary',`data-id="${id}"`)}</div>${[{title:a.id==='dispute'?'Evidence prepared for dispute #DIS-4521':a.id==='subs'?'Renewal reminder drafted for Riya Sharma':a.id==='cash'?'Seven-day cash forecast refreshed':'A new customer opportunity reviewed',time:'12 minutes ago'},{title:a.id==='cart'?'Recovered cart payment received · ₹2,980':'Weekly performance summary prepared',time:'45 minutes ago'}].map(r=>`<div class="recent-row"><div class="icon-tile ${a.tone}">${icon('check',17)}</div><div><strong>${r.title}</strong><p>${r.time}</p></div></div>`).join('')}<a href="#/agent/${id}" class="btn" style="align-self:flex-start">View capabilities ${icon('arrow-right',13)}</a></div>`;}
const commandItems=[...navItems.map(([id,name,ic])=>({name,desc:'Workspace page',icon:ic,path:id==='studio'?'/studio/home':'/payments/'+id})),...agents.map(a=>({name:a.name,desc:'Razorpay agent',icon:a.icon,path:'/agent/'+a.id})),{name:'Approvals',desc:'B2B Customer Agent',icon:'check-circle',path:'/agent/business/approvals'},{name:'Buyers',desc:'B2B Customer Agent',icon:'users',path:'/agent/business/buyers'}];
function commandResults(q=''){return commandItems.filter(x=>(x.name+' '+x.desc).toLowerCase().includes(q.toLowerCase())).slice(0,7).map(x=>`<button class="search-result" data-route="${x.path}">${icon(x.icon,19)}<span>${esc(x.name)}<small>${x.desc}</small></span>${icon('arrow-right',14)}</button>`).join('')||'<p class="muted small" style="padding:15px">No matching pages or agents.</p>';}
function downloadCSV(rows,name){const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\n');const url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Downloaded '+name);}
function answerRay(q){ui.rayQuestion=q;const text=/approv|need|pending/i.test(q)?`${state.pending.length} items need your review, representing ${money(state.pending.reduce((sum,id)=>sum+({sai:21042,shivalik:32193,finch:9886,glow:27122}[id]||0),0))} in potential orders. Start with the introduction batch, then review the quotes and buyer labels.`:/grow|opportun|buyer/i.test(q)?'The agent identified 44 new business buyers this week. 27 are ready for an introduction. PGs and salons are your strongest segments; 19 accounts have already reordered.':`Your B2B agent has generated ₹8.40 L from 82 orders. You have 63 business accounts, 19 repeat buyers, and an average business order of ₹10,244. ${state.paused?'The agent is currently paused.':'The agent is running in review-first mode.'}`;const el=document.getElementById('ray-answer');if(el)el.innerHTML=`<div class="ray-answer"><strong>${esc(q)}</strong><p style="margin-top:9px">${esc(text)}</p><a href="#/agent/business/dashboard" class="small">Open B2B dashboard ${icon('arrow-right',12)}</a></div>`;}
function handleRoot(action,el){
 if(action==='dashboard-ray'){closeDateMenu();openRay(ctx);}
 if(action==='overlay-close')closeOverlay();
 if(action==='toast-close'){clearTimeout(toastTimer);document.getElementById('toast-root').innerHTML='';}
 if(action==='sidebar-toggle'){ui.sidebar=!ui.sidebar;render();}
 if(action==='agent-pause')state.paused?resume():pause();
 if(action==='agent-resume')resume();
 if(action==='agent-pause-confirm'){state.paused=true;log({title:'Agent paused',buyer:'All buyers',detail:'Messages, calls and quotes stopped. Approvals remain queued.'});closeOverlay();render();toast('B2B Customer Agent paused.');}
 if(action==='date-menu-toggle'){ui.rangeOpen=!ui.rangeOpen;render();}
 if(action==='date-range-pick'){ui.rangeOpen=false;update({range:el.dataset.range});document.querySelector('[data-action="date-menu-toggle"]')?.focus({preventScroll:true});}
 if(action==='demo-reset')modal(`<div class="modal-body"><div class="modal-head"><h2>Reset this demo?</h2>${button(icon('x',17),'overlay-close','ghost','aria-label="Close"')}</div><p>Restore the original synthetic workspace, installation flow and six approvals. Your local demo changes will be cleared.</p><div class="modal-actions">${button('Keep my changes','overlay-close')}${button('Reset demo','demo-reset-confirm','primary')}</div></div>`);
 if(action==='demo-reset-confirm'){state=initial();ctx.state=state;Object.keys(ui).forEach(k=>delete ui[k]);ui.slide=0;ui.category='all';persist();closeOverlay(false);nav('/studio/home');toast('Demo reset to its starting state.');}
 if(action==='command-open')modal(`<div class="modal-body"><div class="modal-head"><h2>Search your workspace</h2>${button(icon('x',17),'overlay-close','ghost','aria-label="Close"')}</div><div class="command-search">${icon('search',18)}<input autofocus data-action="command-search" aria-label="Search pages and agents" placeholder="Search pages or agents…"></div><div class="search-results" id="command-results">${commandResults()}</div></div>`);
 if(action==='command-search')document.getElementById('command-results').innerHTML=commandResults(el.value);
 if(action==='notifications')ctx.drawer(`<div class="modal-head"><h2>Notifications</h2>${button(icon('x',17),'overlay-close','ghost','aria-label="Close"')}</div>${badge('Demo updates','blue')}<div class="stack" style="margin-top:23px"><a href="#/agent/business/approvals" class="card"><h3>${state.pending.length} items need your review</h3><p class="muted small">Quotes, buyer introductions and labels</p></a><a href="#/agent/business/dashboard" class="card"><h3>Advance received · ₹15,246</h3><p class="muted small">Urban Nest Co-living · 6 minutes ago</p></a><a href="#/studio/connectors" class="card"><h3>Tally demo connection expiring</h3><p class="muted small">Review the simulated connection status</p></a></div>`);
 if(action==='profile')modal(`<div class="modal-body"><div class="modal-head"><h2>Your workspace</h2>${button(icon('x',17),'overlay-close','ghost','aria-label="Close"')}</div><div class="profile-block"><span class="avatar">NA</span><div><strong>Neha Agarwal</strong><p class="muted small">neha@kesarlinen.in · Workspace owner</p></div></div><div class="card stack"><div class="row between"><span>Business</span><strong>Kesar Linen</strong></div><div class="row between"><span>Workspace</span>${badge('Synthetic prototype','blue')}</div></div><div class="modal-actions">${button('Close','overlay-close','primary')}</div></div>`);
 if(action==='more-products')modal(`<div class="modal-body"><div class="modal-head"><h2>Explore Razorpay</h2>${button(icon('x',17),'overlay-close','ghost','aria-label="Close"')}</div><div class="search-results">${[['Banking','bank','banking'],['Payroll','users','payroll'],['Vendor Payments','folder','vendors'],['Agent Studio','monitor','studio']].map(([name,ic,id])=>`<button class="search-result" data-route="${id==='studio'?'/studio/home':'/payments/'+id}">${icon(ic,20)}<span>${name}<small>Synthetic workspace preview</small></span>${icon('arrow-right',14)}</button>`).join('')}</div></div>`);
 if(action==='payment-search'){ui.paymentSearch=el.value;render();}
 if(action==='payment-status'){ui.paymentStatus=el.value;render();}
 if(action==='payment-export'){if(el.dataset.kind==='settlements')downloadCSV([['Settlement ID','Date','Amount INR','Status'],['set_QK810','2026-10-10',124808,'Settled'],['set_QK721','2026-10-08',98246,'Settled'],['set_QK604','2026-10-06',156310,'Settled']],'razorpay-demo-settlements.csv');else downloadCSV([['Payment ID','Customer','Method','Amount INR','Status','Created'],...transactions],'razorpay-demo-payments.csv');}
 if(action==='report-agent-export')handleDashboard('activity-export',el,ctx);
 if(action==='payment-detail'){const x=transactions.find(x=>x[0]===el.dataset.id);ctx.drawer(`<div class="modal-head"><h2>Payment details</h2>${button(icon('x',17),'overlay-close','ghost','aria-label="Close"')}</div><div class="stack"><div class="card payment-metric"><span class="muted small">${x[0]}</span><strong>${money(x[3])}</strong>${badge(x[4],x[4]==='Captured'?'green':'orange')}</div><div class="card stack">${[['Customer',x[1]],['Payment method',x[2]],['Created',x[5]],['Currency','INR'],['Workspace','Synthetic demo']].map(([k,v])=>`<div class="row between"><span class="muted">${k}</span><strong>${v}</strong></div>`).join('')}</div>${button(icon('download',14)+' Download record','payment-export')}</div>`);}
 if(action==='ray-prompt')answerRay(el.dataset.prompt);
}
function dispatch(event){const el=event.target.closest('[data-action],[data-route]');if(!el||el.disabled)return;if(event.type==='click'&&el.matches('input,select,textarea'))return;if(event.type!=='click'&&!el.matches('input,select,textarea'))return;const discrete=el.matches('select,input[type=checkbox],input[type=radio],input[type=file]');if(event.type==='input'&&discrete||event.type==='change'&&!discrete)return;if(el.dataset.route){if(event.type==='click'){event.preventDefault();nav(el.dataset.route);}return;}const action=el.dataset.action;handleRoot(action,el);handleStudio(action,el,ctx);handleOnboarding(action,el,ctx);handleDashboard(action,el,ctx);handleRay(action,el,ctx);}
document.addEventListener('click',event=>{if(ui.rangeOpen&&!event.target.closest('.date-control'))closeDateMenu();if(event.target.closest('.skip-link')){event.preventDefault();document.getElementById('main').focus();return;}if(event.target.hasAttribute('data-backdrop'))closeOverlay();else dispatch(event);});
document.addEventListener('input',dispatch);document.addEventListener('change',dispatch);
document.addEventListener('keydown',event=>{
 const trigger=event.target.closest('[data-action="date-menu-toggle"]');
 if(trigger&&['ArrowDown','ArrowUp'].includes(event.key)){
  event.preventDefault();ui.rangeOpen=true;render();
  const items=[...document.querySelectorAll('.date-option')];
  (event.key==='ArrowUp'?items.at(-1):items.find(x=>x.getAttribute('aria-checked')==='true')||items[0])?.focus();
 }
 if(event.target.matches('.date-option')&&['ArrowDown','ArrowUp','Home','End'].includes(event.key)){
  event.preventDefault();const items=[...document.querySelectorAll('.date-option')],index=items.indexOf(event.target);
  items[event.key==='Home'?0:event.key==='End'?items.length-1:(index+(event.key==='ArrowDown'?1:-1)+items.length)%items.length]?.focus();
 }
 if(event.key==='Tab'&&ui.rangeOpen){closeDateMenu(event.target.matches('.date-option'));}
});
document.addEventListener('submit',event=>{if(event.target.id==='dashboard-ray-form'){event.preventDefault();handleRay('ray-send',null,ctx);}else if(event.target.id==='ray-form'){event.preventDefault();const value=document.getElementById('ray-question').value.trim();if(value)answerRay(value);}});
document.addEventListener('keydown',event=>{if(['Enter',' '].includes(event.key)&&event.target.matches('[role="button"][data-action]')){event.preventDefault();event.target.click();}if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();handleRoot('command-open',document.body);}if(event.key==='Escape'){closeDateMenu(true);closeOverlay();if(ui.sidebar){ui.sidebar=false;render();}}if(event.key==='Tab'&&document.getElementById('overlay-root').firstChild){const items=[...document.querySelectorAll('#overlay-root button:not(:disabled),#overlay-root a[href],#overlay-root input:not(:disabled),#overlay-root select:not(:disabled),#overlay-root textarea:not(:disabled),#overlay-root [tabindex="0"]')].filter(x=>x.offsetParent!==null);const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
document.addEventListener('pointerover',event=>{if(event.target.closest('[data-carousel]'))carouselHold=true;});document.addEventListener('pointerout',event=>{if(event.target.closest('[data-carousel]')&&!event.relatedTarget?.closest?.('[data-carousel]'))carouselHold=false;});document.addEventListener('focusin',event=>{if(event.target.closest('[data-carousel]'))carouselHold=true;});document.addEventListener('focusout',event=>{if(event.target.closest('[data-carousel]')&&!event.relatedTarget?.closest?.('[data-carousel]'))carouselHold=false;});
setInterval(()=>{if(route()==='/studio/home'&&!carouselHold&&!document.hidden&&!matchMedia('(prefers-reduced-motion:reduce)').matches&&!document.getElementById('overlay-root').firstChild){ui.slide=((ui.slide||0)+1)%4;changeSlide(ctx);}},7000);
window.addEventListener('hashchange',()=>{closeDateMenu();closeOverlay(false);ui.sidebar=false;render();});window.addEventListener('resize',()=>{document.getElementById('sidebar').inert=matchMedia('(max-width:700px)').matches&&!ui.sidebar;});
render();
